  select md5('democ:m:allentown-realty-latino:0')::uuid, b, (select id from users where phone = '+15705559653'), 'owner', 'Ramón García', null, '{"es":"Agente de bienes raíces y dueño","en":"Real estate agent and owner"}'::jsonb, 'https://images.pexels.com/photos/1681010/pexels-photo-1681010.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Trabajo en español y en inglés. Te enseño la casa, te explico la cuota estimada y los gastos del cierre antes de que ofertes.","en":"I work in Spanish and English. I show you the home and explain the estimated payment and closing costs before you make an offer."}'::jsonb, '{all}'::text[], 'active', true, 0, 2018, true, true
