  select md5('democ:m:reading-bienes-raices-plus:0')::uuid, b, (select id from users where phone = '+15705559656'), 'owner', 'Carlos Torres', null, '{"es":"Agente de bienes raíces y dueño","en":"Real estate agent and owner"}'::jsonb, 'https://images.pexels.com/photos/16160871/pexels-photo-16160871.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Llevo desde 2016 ayudando a vecinos del valle a comprar y a vender. Mi trabajo es que entiendas cada papel que firmas.","en":"Since 2016 I have helped neighbors across the valley buy and sell. My job is that you understand every paper you sign."}'::jsonb, '{all}'::text[], 'active', true, 0, 2016, true, true
