  insert into business_stats_cache (business_id, plan, verified, photo_count) values (b, 'pro', true, 7) on conflict (business_id) do update set plan = 'pro', verified = true, photo_count = excluded.photo_count, updated_at = now();
  insert into subscriptions (business_id, status, cycle, price_cents, trial_started_at, trial_ends_at, trial_choice, current_period_end, created_at) values (b, 'active', 'month', 1499, '2009-04-20'::date, '2009-04-20'::date + 30, 'card', now() + interval '25 days', '2009-04-20'::date) on conflict (business_id) do nothing;
