  select md5('democ:m:casa-segura-bienes-raices:0')::uuid, b, (select id from users where phone = '+15705559657'), 'owner', 'Rafael Polanco', null, '{"es":"Agente de bienes raíces y dueño","en":"Real estate agent and owner"}'::jsonb, 'https://images.pexels.com/photos/11579595/pexels-photo-11579595.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Trabajo en español y en inglés. Te enseño la casa, te explico la cuota estimada y los gastos del cierre antes de que ofertes.","en":"I work in Spanish and English. I show you the home and explain the estimated payment and closing costs before you make an offer."}'::jsonb, '{all}'::text[], 'active', true, 0, 2009, true, true
