  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cobran por ver una propiedad?","en":"Do you charge to see a property?"}'::jsonb, '{"es":"No. Ver una propiedad es gratis. Nunca pagues un depósito antes de ver la propiedad y firmar el contrato.","en":"No. Viewing a property is free. Never pay a deposit before seeing the property and signing the lease."}'::jsonb, 0);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Puedo comprar con ITIN?","en":"Can I buy with an ITIN?"}'::jsonb, '{"es":"Sí. Trabajamos con prestamistas que aceptan ITIN. Suelen pedir un enganche desde 15 %. Nadie garantiza la aprobación antes de revisar tus papeles.","en":"Yes. We work with lenders that accept ITIN. They usually ask for a down payment from 15%. No one guarantees approval before reviewing your papers."}'::jsonb, 1);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué significa «cuota estimada»?","en":"What does “estimated payment” mean?"}'::jsonb, '{"es":"Es el pago mensual aproximado con impuestos y seguro, según el enganche que elijas. La cuota real depende del préstamo que te aprueben.","en":"It is the approximate monthly payment with taxes and insurance, based on the down payment you choose. The real payment depends on the loan you are approved for."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cuánto tiempo tarda la precalificación?","en":"How long does pre-qualification take?"}'::jsonb, '{"es":"Normalmente 5 días hábiles. Es gratis.","en":"Usually 5 business days. It is free."}'::jsonb, 3);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo reservo una visita?","en":"How do I book a showing?"}'::jsonb, '{"es":"En cada propiedad eliges una hora libre y nos llega al instante. Si no puedes ir, cancela desde la app para liberar el horario.","en":"On each property you pick a free time and it reaches us instantly. If you cannot make it, cancel from the app to free up the slot."}'::jsonb, 4);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Quién paga la comisión?","en":"Who pays the commission?"}'::jsonb, '{"es":"Lo hablamos por escrito antes de firmar nada, para que sepas exactamente cuánto es y quién lo paga.","en":"We discuss it in writing before you sign anything, so you know exactly how much it is and who pays it."}'::jsonb, 5);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Atienden en español?","en":"Do you work in Spanish?"}'::jsonb, '{"es":"Sí, todo el equipo atiende en español e inglés en Reading.","en":"Yes, the whole team works in Spanish and English in Reading."}'::jsonb, 6);
