  values (b, 'scr', 'NEG-INMUEBLE', array['NEG-INMUEBLE-02','NEG-INMUEBLE-03','NEG-INMUEBLE-05']::text[], 'Casa Fácil Bilingüe', 'active', 'self', (select id from users where phone = '+15705559670'), 'local', '430 Lackawanna Ave, Scranton PA', st_geogfromtext('POINT(-75.65677 41.407386)'), false, null, '+15705550115', false, array['es','en']::text[], '{"es":"Agente bilingüe en Scranton desde 2008. Ver una casa es gratis; el precio, la cuota estimada y lo que pagas al cerrar se dicen antes de firmar. Trabajamos con compradores con ITIN. El comprador no paga comisión. Hablamos español e inglés.","en":"Bilingual realtor in Scranton since 2008. Viewing a home is free; the price, estimated payment and closing costs are stated before you sign. We work with ITIN buyers. The buyer pays no commission. We speak Spanish and English."}'::jsonb, 2008, array['sin-cita','acepta-tarjeta','estacionamiento','acepta-itin','section-8']::text[], array['rentar','comprar','sinssn','itin','s8','utilidades','amueblado','cuarto','nocom','visita','esp','y10']::text[], '{local}', '{"m":"shop","inm_der":["eta","fee"],"tarjeta":{"eta":{"es":"7 casas en venta","en":"7 homes for sale"},"fee":{"es":"Desde $37,000 · comprador sin comisión","en":"From $37,000 · no buyer commission"}}}'::jsonb, 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20viewBox%3D''0%200%20120%20120''%3E%3Crect%20width%3D''120''%20height%3D''120''%20rx%3D''26''%20fill%3D''%230F4C5C''%2F%3E%3Ctext%20x%3D''60''%20y%3D''76''%20font-family%3D''Arial%2CHelvetica%2Csans-serif''%20font-size%3D''46''%20font-weight%3D''700''%20fill%3D''%23F6E7B0''%20text-anchor%3D''middle''%3ECF%3C%2Ftext%3E%3C%2Fsvg%3E', array['svc','staff','nov']::text[], 'emp', true);
  insert into business_stats_cache (business_id, plan, verified, photo_count) values (b, 'pro', true, 6) on conflict (business_id) do update set plan = 'pro', verified = true, photo_count = excluded.photo_count, updated_at = now();
