  insert into users (phone, phone_verified_at, first_name, last_name, lang, home_city_id, is_test, created_at) values ('+15705559673', now(), 'Edwin', 'Núñez', 'es', 'alw', false, now() - interval '400 days') on conflict (phone) do nothing;
