  values (b, 'alw', 'NEG-INMUEBLE', array['NEG-INMUEBLE-03','NEG-INMUEBLE-05','NEG-INMUEBLE-01']::text[], 'Agente del Comprador Allentown', 'active', 'self', (select id from users where phone = '+15705559673'), 'local', '198 Linden St, Allentown PA', st_geogfromtext('POINT(-75.468254 40.601078)'), false, null, '+16105550191', true, array['es','en']::text[], '{"es":"Agente del comprador en Allentown desde 2012. Ver una casa es gratis; el precio, la cuota estimada y lo que pagas al cerrar se dicen antes de firmar. Trabajamos con compradores con ITIN. El comprador no paga comisión. Hablamos español e inglés.","en":"Buyer''s agent in Allentown since 2012. Viewing a home is free; the price, estimated payment and closing costs are stated before you sign. We work with ITIN buyers. The buyer pays no commission. We speak Spanish and English."}'::jsonb, 2012, array['sin-cita','acepta-tarjeta','estacionamiento','acepta-itin','section-8','mascotas']::text[], array['rentar','comprar','sinssn','itin','s8','mascotas','utilidades','nocom','visita','esp','y10']::text[], '{local}', '{"m":"shop","inm_der":["eta","fee"],"tarjeta":{"eta":{"es":"5 casas en venta","en":"5 homes for sale"},"fee":{"es":"Desde $65,000 · comprador sin comisión","en":"From $65,000 · no buyer commission"}}}'::jsonb, 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20viewBox%3D''0%200%20120%20120''%3E%3Crect%20width%3D''120''%20height%3D''120''%20rx%3D''26''%20fill%3D''%2322313F''%2F%3E%3Ctext%20x%3D''60''%20y%3D''76''%20font-family%3D''Arial%2CHelvetica%2Csans-serif''%20font-size%3D''46''%20font-weight%3D''700''%20fill%3D''%23F4B942''%20text-anchor%3D''middle''%3EAC%3C%2Ftext%3E%3C%2Fsvg%3E', array['svc','staff','nov']::text[], 'emp', true);
  insert into business_stats_cache (business_id, plan, verified, photo_count) values (b, 'pro', true, 6) on conflict (business_id) do update set plan = 'pro', verified = true, photo_count = excluded.photo_count, updated_at = now();
  insert into subscriptions (business_id, status, cycle, price_cents, trial_started_at, trial_ends_at, trial_choice, current_period_end, created_at) values (b, 'active', 'month', 1499, '2012-06-16'::date, '2012-06-16'::date + 30, 'card', now() + interval '21 days', '2012-06-16'::date) on conflict (business_id) do nothing;
