  insert into items (business_id, module, section_id, name, descr, price_cents, unit, tax_pct, photos, channels, stock_mode, stock_left, stock_par, duration_min, price_from, svc_opts, svc_kind, svc_attrs, deposit_cents, attrs, featured, sort, tags) values (b, 'svc', s, '{"es":"Consulta gratis para primer comprador","en":"Free first-time buyer consultation"}'::jsonb, '{"es":"Te explicamos paso a paso cómo comprar, qué papeles llevar y qué programas ayudan con el enganche.","en":"We explain step by step how to buy, which papers to bring and which programs help with the down payment."}'::jsonb, 0, 'u', 6, array['https://images.pexels.com/photos/36729941/pexels-photo-36729941.jpeg?auto=compress&cs=tinysrgb&h=600']::text[], array['dlv','pick']::text[], 'none', 0, 10, 60, false, '[]'::jsonb, null, '{}'::jsonb, 0, '{}'::jsonb, false, 0, '{}'::text[]);
