  insert into business_stats_cache (business_id, plan, verified, photo_count) values (b, 'pro', true, 6) on conflict (business_id) do update set plan = 'pro', verified = true, photo_count = excluded.photo_count, updated_at = now();
  insert into subscriptions (business_id, status, cycle, price_cents, trial_started_at, trial_ends_at, trial_choice, current_period_end, created_at) values (b, 'active', 'month', 1499, '2017-06-23'::date, '2017-06-23'::date + 30, 'card', now() + interval '28 days', '2017-06-23'::date) on conflict (business_id) do nothing;
