  select md5('democ:m:casa-propia-scranton-compradores:0')::uuid, b, (select id from users where phone = '+15705559680'), 'owner', 'Víctor Medina', null, '{"es":"Agente de bienes raíces y dueño","en":"Real estate agent and owner"}'::jsonb, 'https://images.pexels.com/photos/16160952/pexels-photo-16160952.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Compré mi primera casa con ITIN en 2009 y por eso sé qué preguntas hacer. Ver una casa contigo es gratis y el costo de mudarte, claro desde el principio.","en":"I bought my first home with an ITIN in 2009, so I know which questions to ask. Viewing a home with me is free and the cost to move in is clear from the start."}'::jsonb, '{all}'::text[], 'active', true, 0, 2017, true, true
