do $$
declare b text := 'vendedores-del-valle-hazleton'; s bigint; it bigint;
begin
  if exists (select 1 from businesses where id = b) then return; end if;
  insert into users (phone, phone_verified_at, first_name, last_name, lang, home_city_id, is_test, created_at) values ('+15705559682', now(), 'Ramón', 'Jiménez', 'es', 'hzl', false, now() - interval '400 days') on conflict (phone) do nothing;
