  select md5('democ:m:casas-en-venta-hazleton-centro:0')::uuid, b, (select id from users where phone = '+15705559692'), 'owner', 'Ramón Castillo', null, '{"es":"Agente de bienes raíces y dueño","en":"Real estate agent and owner"}'::jsonb, 'https://images.pexels.com/photos/11579595/pexels-photo-11579595.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Llevo desde 2012 ayudando a vecinos del valle a comprar y a vender. Mi trabajo es que entiendas cada papel que firmas.","en":"Since 2012 I have helped neighbors across the valley buy and sell. My job is that you understand every paper you sign."}'::jsonb, '{all}'::text[], 'active', true, 0, 2012, true, true
