do $$
declare b text := 'casas-allentown-selectas'; s bigint; it bigint;
begin
  if exists (select 1 from businesses where id = b) then return; end if;
  insert into users (phone, phone_verified_at, first_name, last_name, lang, home_city_id, is_test, created_at) values ('+15705559693', now(), 'Francisco', 'Vargas', 'es', 'alw', false, now() - interval '400 days') on conflict (phone) do nothing;
  insert into businesses (id, city_id, category_id, subcategory_ids, name, status, origin, owner_user_id, operation, address, geo, works_from_home, service_radius_mi, phone, whatsapp, languages, about, founded_year, amenities, filter_values, payment_modes, category_attrs, logo_url, modules_on, svc_model, is_demo)
  values (b, 'alw', 'NEG-INMUEBLE', array['NEG-INMUEBLE-05','NEG-INMUEBLE-06']::text[], 'Casas Allentown Selectas', 'active', 'self', (select id from users where phone = '+15705559693'), 'local', '132 Linden St, Allentown PA', st_geogfromtext('POINT(-75.470399 40.601127)'), false, null, '+16105550129', true, array['es','en']::text[], '{"es":"Casas en venta en Allentown desde 2013. Ver una casa es gratis; el precio, la cuota estimada y lo que pagas al cerrar se dicen antes de firmar. Trabajamos con compradores con ITIN. El comprador no paga comisión. Hablamos español e inglés.","en":"Homes for sale in Allentown since 2013. Viewing a home is free; the price, estimated payment and closing costs are stated before you sign. We work with ITIN buyers. The buyer pays no commission. We speak Spanish and English."}'::jsonb, 2013, array['sin-cita','acepta-tarjeta','estacionamiento','acepta-itin']::text[], array['rentar','comprar','sinssn','itin','utilidades','cuarto','nocom','visita','esp','y10']::text[], '{local}', '{"m":"shop","inm_der":["eta","fee"],"tarjeta":{"eta":{"es":"5 casas en venta","en":"5 homes for sale"},"fee":{"es":"Desde $58,000 · comprador sin comisión","en":"From $58,000 · no buyer commission"}}}'::jsonb, 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20viewBox%3D''0%200%20120%20120''%3E%3Crect%20width%3D''120''%20height%3D''120''%20rx%3D''26''%20fill%3D''%2322313F''%2F%3E%3Ctext%20x%3D''60''%20y%3D''76''%20font-family%3D''Arial%2CHelvetica%2Csans-serif''%20font-size%3D''46''%20font-weight%3D''700''%20fill%3D''%23F4B942''%20text-anchor%3D''middle''%3ECA%3C%2Ftext%3E%3C%2Fsvg%3E', array['svc','staff','nov']::text[], 'emp', true);
  insert into business_stats_cache (business_id, plan, verified, photo_count) values (b, 'pro', true, 6) on conflict (business_id) do update set plan = 'pro', verified = true, photo_count = excluded.photo_count, updated_at = now();
  insert into subscriptions (business_id, status, cycle, price_cents, trial_started_at, trial_ends_at, trial_choice, current_period_end, created_at) values (b, 'active', 'month', 1499, '2013-05-16'::date, '2013-05-16'::date + 30, 'card', now() + interval '21 days', '2013-05-16'::date) on conflict (business_id) do nothing;
insert into business_hours (business_id, weekday, open, ranges) values (b, 0, false, '[]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 1, true, '[["09:00","18:00"]]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 2, true, '[["09:00","18:00"]]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 3, true, '[["09:00","18:00"]]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 4, true, '[["09:00","18:00"]]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 5, true, '[["09:00","18:00"]]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 6, true, '[["09:00","13:00"]]'::jsonb);
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-allentown-selectas:0')::uuid, 'business', b, '33258708', 'Pexels', 0) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-allentown-selectas:1')::uuid, 'business', b, '7578859', 'Pexels', 1) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-allentown-selectas:2')::uuid, 'business', b, '36729941', 'Pexels', 2) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-allentown-selectas:3')::uuid, 'business', b, '7578866', 'Pexels', 3) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-allentown-selectas:4')::uuid, 'business', b, '7937330', 'Pexels', 4) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-allentown-selectas:5')::uuid, 'business', b, '8815820', 'Pexels', 5) on conflict (id) do nothing;
  insert into business_members (id, business_id, user_id, kind, display_name, nickname, role, photo_url, languages, specialties, bio, panel_access, status, show_on_page, sort, since_year, same_as_business_hours, takes_bookings)
  select md5('democ:m:casas-allentown-selectas:0')::uuid, b, (select id from users where phone = '+15705559693'), 'owner', 'Francisco Vargas', null, '{"es":"Agente de bienes raíces y dueño","en":"Real estate agent and owner"}'::jsonb, 'https://images.pexels.com/photos/1681010/pexels-photo-1681010.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Trabajo en español y en inglés. Te enseño la casa, te explico la cuota estimada y los gastos del cierre antes de que ofertes.","en":"I work in Spanish and English. I show you the home and explain the estimated payment and closing costs before you make an offer."}'::jsonb, '{all}'::text[], 'active', true, 0, 2013, true, true
  where not exists (select 1 from business_members x where x.id = md5('democ:m:casas-allentown-selectas:0')::uuid);
  insert into business_members (id, business_id, user_id, kind, display_name, nickname, role, photo_url, languages, specialties, bio, panel_access, status, show_on_page, sort, since_year, same_as_business_hours, takes_bookings)
  select md5('democ:m:casas-allentown-selectas:1')::uuid, b, null, 'staff', 'Ángel Almonte', null, '{"es":"Agente","en":"Agent"}'::jsonb, 'https://images.pexels.com/photos/13430313/pexels-photo-13430313.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, null, '{}'::text[], 'active', true, 1, 2018, true, true
  where not exists (select 1 from business_members x where x.id = md5('democ:m:casas-allentown-selectas:1')::uuid);
  insert into business_members (id, business_id, user_id, kind, display_name, nickname, role, photo_url, languages, specialties, bio, panel_access, status, show_on_page, sort, since_year, same_as_business_hours, takes_bookings)
  select md5('democ:m:casas-allentown-selectas:2')::uuid, b, null, 'staff', 'Yanira Martínez', null, '{"es":"Coordinación de visitas","en":"Showing coordinator"}'::jsonb, 'https://images.pexels.com/photos/13430312/pexels-photo-13430312.jpeg?auto=compress&cs=tinysrgb&w=160', array['es']::text[], '[]'::jsonb, null, '{}'::text[], 'active', true, 2, 2014, true, false
  where not exists (select 1 from business_members x where x.id = md5('democ:m:casas-allentown-selectas:2')::uuid);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cobran por ver una propiedad?","en":"Do you charge to see a property?"}'::jsonb, '{"es":"No. Ver una propiedad es gratis. Nunca pagues un depósito antes de ver la propiedad y firmar el contrato.","en":"No. Viewing a property is free. Never pay a deposit before seeing the property and signing the lease."}'::jsonb, 0);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Puedo comprar con ITIN?","en":"Can I buy with an ITIN?"}'::jsonb, '{"es":"Sí. Trabajamos con prestamistas que aceptan ITIN. Suelen pedir un enganche desde 10 %. Nadie garantiza la aprobación antes de revisar tus papeles.","en":"Yes. We work with lenders that accept ITIN. They usually ask for a down payment from 10%. No one guarantees approval before reviewing your papers."}'::jsonb, 1);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué significa «cuota estimada»?","en":"What does “estimated payment” mean?"}'::jsonb, '{"es":"Es el pago mensual aproximado con impuestos y seguro, según el enganche que elijas. La cuota real depende del préstamo que te aprueben.","en":"It is the approximate monthly payment with taxes and insurance, based on the down payment you choose. The real payment depends on the loan you are approved for."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cuánto tiempo tarda la precalificación?","en":"How long does pre-qualification take?"}'::jsonb, '{"es":"Normalmente 1 día hábiles. Es gratis.","en":"Usually 1 business day. It is free."}'::jsonb, 3);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo reservo una visita?","en":"How do I book a showing?"}'::jsonb, '{"es":"En cada propiedad eliges una hora libre y nos llega al instante. Si no puedes ir, cancela desde la app para liberar el horario.","en":"On each property you pick a free time and it reaches us instantly. If you cannot make it, cancel from the app to free up the slot."}'::jsonb, 4);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿El comprador paga comisión?","en":"Does the buyer pay a commission?"}'::jsonb, '{"es":"En las casas que listamos nosotros, el comprador no paga comisión.","en":"On the homes we list, the buyer pays no commission."}'::jsonb, 5);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Atienden en español?","en":"Do you work in Spanish?"}'::jsonb, '{"es":"Sí, todo el equipo atiende en español e inglés en Allentown.","en":"Yes, the whole team works in Spanish and English in Allentown."}'::jsonb, 6);
