  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-del-lehigh:0')::uuid, 'business', b, '36729941', 'Pexels', 0) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-del-lehigh:1')::uuid, 'business', b, '7578859', 'Pexels', 1) on conflict (id) do nothing;
