  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-del-lehigh:3')::uuid, 'business', b, '8815820', 'Pexels', 3) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:casas-del-lehigh:4')::uuid, 'business', b, '7937330', 'Pexels', 4) on conflict (id) do nothing;
