  insert into business_members (id, business_id, user_id, kind, display_name, nickname, role, photo_url, languages, specialties, bio, panel_access, status, show_on_page, sort, since_year, same_as_business_hours, takes_bookings)
  select md5('democ:m:casas-berks-en-venta:0')::uuid, b, (select id from users where phone = '+15705559703'), 'owner', 'Yokasta Vargas', null, '{"es":"Agente de bienes raíces y dueño","en":"Real estate agent and owner"}'::jsonb, 'https://images.pexels.com/photos/16160871/pexels-photo-16160871.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Compré mi primera casa con ITIN en 2009 y por eso sé qué preguntas hacer. Ver una casa contigo es gratis y el costo de mudarte, claro desde el principio.","en":"I bought my first home with an ITIN in 2009, so I know which questions to ask. Viewing a home with me is free and the cost to move in is clear from the start."}'::jsonb, '{all}'::text[], 'active', true, 0, 2015, true, true
  where not exists (select 1 from business_members x where x.id = md5('democ:m:casas-berks-en-venta:0')::uuid);
