insert into reviews (business_id, city_id, user_id, operation_id, src, stars, body, lang, answers, facts, reply, reply_at, reply_by, reply_lang, created_at)
select v.biz, v.city, u.id, o.id, v.src, v.stars, v.body, v.lang, v.ans::jsonb, v.facts::jsonb, v.reply, case when v.reply is null then null else pg_temp.c_ts(v.rd, v.rm) end, case when v.reply is null then null else ow.user_id end, v.rlang, pg_temp.c_ts(v.cd, v.cm)
  from (values
('bienes-raices-hazleton-hogar', 'hzl', '+15705558692', 'D-3400001', 'cita', 5, 'Muy profesionales. María nos enseñó la casa a la hora acordada y contestó todas las preguntas. Cerramos sin problemas.', 'es', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2017-08-31","que":"visita","tot":19200000}', 'Te agradecemos mucho, Héctor. Ese es el trato que queremos dar siempre.', -3363, 1173, 'es', -3365, 743),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558662', 'D-3400003', 'cita', 5, 'Excelente atención. Vendieron mi casa en pocas semanas, con fotos buenas y buena comunicación. Ya les mandé a dos amigos.', 'es', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2017-12-23","que":"visita","tot":296000}', null, null, null, null, -3245, 1177),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558537', 'D-3400006', 'cita', 4, 'Todo bien. La visita empezó unos minutos tarde pero avisaron.', 'es', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2019-03-01","que":"visita","tot":17600000}', null, null, null, null, -2815, 929),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558557', 'D-3400007', 'cita', 5, 'Muy profesionales. Las fotos del anuncio eran fieles a la casa. Nos dijeron de entrada cuánto íbamos a pagar para mudarnos, sin sorpresas. Los volveríamos a llamar.', 'es', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2019-06-03","que":"visita","tot":14000000}', 'Gracias por tu reseña, Carmen. Le paso tus palabras a todo el equipo.', -2724, 998, 'es', -2724, 848),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558521', 'D-3400010', 'cita', 3, 'Regular. La propiedad no estaba como en las fotos y tardaron en contestar. Esperaba más.', 'es', '{"trato":0,"mudarOk":-1,"verGratis":0,"fotosOk":0,"llegaron":"b","claro":-1}', '{"dia":"2020-02-28","que":"visita","tot":14900000}', 'Nancy, gracias por tu honestidad. Avísanos si quieres que lo revisemos de nuevo, sin costo.', -2447, 548, 'es', -2449, 568),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558727', 'D-3400012', 'cita', 4, 'All good. The process took a bit longer than expected, though we always knew where we stood.', 'en', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2020-03-28","que":"visita","tot":16200000}', null, null, null, null, -2423, 1210),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558567', 'D-3400014', 'cita', 4, 'Todo bien. El proceso tomó un poco más de lo esperado, aunque siempre supimos en qué íbamos. La visita empezó unos minutos tarde pero avisaron. Recomendados.', 'es', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2020-06-17","que":"visita","tot":19200000}', null, null, null, null, -2340, 1071),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558647', 'D-3400016', 'cita', 3, 'Regular. La propiedad no estaba como en las fotos y tardaron en contestar. Esperaba más.', 'es', '{"trato":0,"mudarOk":-1,"verGratis":0,"fotosOk":0,"llegaron":"b","claro":-1}', '{"dia":"2020-10-31","que":"visita","tot":14900000}', 'Gracias por decírnoslo, Alberto. Tomamos nota de lo de la demora y ya lo estamos mejorando.', -2200, 715, 'es', -2202, 579),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558712', 'D-3400018', 'cita', 5, 'Nos ayudaron muchísimo. Las fotos del anuncio eran fieles a la casa.', 'es', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2021-03-01","que":"visita","tot":11500000}', 'Te agradecemos mucho, Luis. Ese es el trato que queremos dar siempre.', -2084, 990, 'es', -2086, 934),
('bienes-raices-hazleton-hogar', 'hzl', '+15705558687', 'D-3400021', 'cita', 5, 'Excelente atención. Vendieron mi casa en pocas semanas, con fotos buenas y buena comunicación. Las fotos del anuncio eran fieles a la casa.', 'es', '{"trato":1,"mudarOk":1,"verGratis":1,"fotosOk":1,"llegaron":"a","claro":1}', '{"dia":"2021-10-05","que":"visita","tot":14000000}', 'Gracias por tu reseña, José. Le paso tus palabras a todo el equipo.', -1866, 857, 'es', -1868, 927),
